    level: LV,
    lessonCategory: LessonCategory.VOCABULARY,
    instruction: I.reading,
    passageTitle: '두 가지 표현',
    passage:
      '상대방이 내 말을 믿지 않을 때는 “정말 그렇다니까요.”처럼 강하게 다시 말할 수 있어요. 반대로 계획과 다르게 좋지 않은 결과가 생겼을 때는 “결국 놓치고 말았어요.”처럼 말할 수 있어요.',
